import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync } from 'node:fs';
const base = new URL('../plugins/folia-lyrics-skin/qml/styles/tempera/', import.meta.url);
async function source() {
  assert.ok(existsSync(new URL('kernel.mjs', base)), 'Tempera actual source kernel must exist');
  return import(new URL('kernel.mjs', base));
}
function line(text, start = 0, index = 0) {
  return {
    fullText: text,
    sourceIndex: index,
    startTime: start,
    endTime: start + 3,
    words: [{ text, startTime: start, endTime: start + 3 }],
    autoWordSegments: [text],
    renderHints: { renderEndTime: start + 3 },
  };
}
test('All 121 actual source composition profiles and drawers exist without a fallback replacement', async () => {
  const k = await source();
  assert.equal(k.TEMPERA_SHOT_KINDS.length, 121);
  assert.equal(new Set(k.TEMPERA_SHOT_KINDS).size, 121);
  for (const kind of k.TEMPERA_SHOT_KINDS) {
    assert.equal(typeof k.resolveTemperaComposition(kind), 'function', kind);
    assert.ok(k.resolveTemperaShotProfile(kind).region);
  }
  assert.notEqual(
    k.resolveTemperaComposition('duo-split'),
    k.resolveTemperaComposition('iris-hole'),
  );
});
test('Source semantic segmentation uses saved boundaries before auto ICU and retimes only untimed punctuation', async () => {
  const k = await source(),
    l = line('hello, world');
  l.words = [
    { text: 'hello', startTime: 0, endTime: 1 },
    { text: 'world', startTime: 2, endTime: 3 },
  ];
  l.wordSegments = ['hello, ', 'world'];
  l.autoWordSegments = ['hel', 'lo', ',', ' ', 'world'];
  const segments = k.buildTemperaSegments(l);
  assert.equal(segments.map((p) => p.text).join(''), l.fullText);
  assert.deepEqual(
    segments.map((p) => p.text),
    ['hello,', ' ', 'world'],
  );
  l.wordSegments = [];
  l.autoWordSegments = ['hello', ',', ' ', 'world'];
  const comma = k.buildTemperaSegments(l)[0].graphemes.find((g) => g.char === ',');
  assert.equal(comma.startTime, 1);
  assert.equal(comma.endTime, 1);
});
test('Sparse original sourceIndex survives paragraph compilation and next valid source line cuts the render tail', async () => {
  const k = await source(),
    first = line('first line', 0, 5),
    second = line('last line', 4, 19);
  first.renderHints = { renderEndTime: 20 };
  const program = k.compileTemperaProgram([first, second], 'test', { wholeLineLyrics: true });
  assert.deepEqual(
    program.paragraphs.flatMap((p) => p.lines.map((l) => l.sourceIndex)),
    [5, 19],
  );
  assert.equal(program.paragraphs[0].lines[0].renderEndTime, 4);
  assert.deepEqual(
    program.paragraphs.flatMap((p) =>
      p.shots.filter((s) => !s.isBridge).flatMap((s) => s.slices.map((v) => v.lineIndex)),
    ),
    [5, 19],
  );
});
test('Tempera defaults preserve full colour/inversion/post-process/image and source motion settings', async () => {
  const k = await source(),
    t = k.tuning({});
  assert.equal(t.cameraIntensity, 1);
  assert.equal(t.glyphSettleStretch, 0.5);
  assert.equal(t.textInversion, true);
  assert.equal(t.colorMode, 'duo');
  assert.equal(t.textureResolution, 1.5);
  assert.equal(t.postProcessEnabled, true);
  assert.equal(t.postProcessGrain, 0.2);
  assert.equal(t.postProcessVignette, 0.85);
  assert.equal(t.postProcessLensDistortion, 0.3);
  assert.equal(t.layerImageFrequency, 0.6);
  assert.equal(k.tuning({ temperaCameraIntensity: 99 }).cameraIntensity, 2);
});
test('Compiled program, every profile, motion, palette and image placement match the independent pinned source', async () => {
  const k = await source(),
    original = await import(
      'data:text/javascript;base64,' + Buffer.from(sourceOracleCode).toString('base64')
    );
  const lines = Array.from({ length: 14 }, (_, i) => {
    const l = line(i % 3 === 0 ? '我想你，不曾离开' : 'Hello 👩🏽‍💻 world!', i * 4, i);
    l.autoWordSegments =
      i % 3 === 0
        ? ['我', '想', '你', '，', '不曾', '离开']
        : ['Hello', ' ', '👩🏽‍💻', ' ', 'world', '!'];
    if (i > 6) l.isChorus = true;
    return l;
  });
  for (const wholeLineLyrics of [false, true])
    assert.deepEqual(
      k.compileTemperaProgram(lines, 37, { wholeLineLyrics }),
      original.compileTemperaProgram(lines, 37, { wholeLineLyrics }),
    );
  for (const kind of k.TEMPERA_SHOT_KINDS)
    assert.deepEqual(k.resolveTemperaShotProfile(kind), original.resolveTemperaShotProfile(kind));
  const theme = {
    backgroundColor: '#101020',
    primaryColor: '#fafafa',
    secondaryColor: '#aaffcc',
    accentColor: '#ffaabb',
  };
  for (const colorMode of ['duo', 'mono', 'gradient'])
    assert.deepEqual(
      k.resolveTemperaPalette(theme, { colorMode }, ['#ff1111', '#aaff55', '#5588ff', '#ffee22']),
      original.resolveTemperaPalette(theme, { colorMode }, [
        '#ff1111',
        '#aaff55',
        '#5588ff',
        '#ffee22',
      ]),
    );
  const glyph = {
    startTime: 1,
    endTime: 2,
    settleTime: 3,
    enterX: 64,
    enterY: -8,
    enterRotation: 0.3,
    enterScale: 0.7,
    rotation: 0.05,
    releaseTime: 8,
    trackingX: 24,
    trackingY: -60,
  };
  for (const enterStyle of [
    'slide',
    'from-left',
    'from-right',
    'from-above',
    'from-below',
    'swing',
    'stamp',
  ])
    for (const time of [0, 1, 1.12, 1.5, 2, 3, 5, 10])
      for (const amount of [0, 0.65, 1, 2])
        assert.deepEqual(
          k.resolveTemperaGlyphMotion(Object.assign({ enterStyle }, glyph), time, amount),
          original.resolveTemperaGlyphMotion(Object.assign({ enterStyle }, glyph), time, amount),
        );
  for (const kind of ['block-wipe', 'camera-pan', 'shape-carry'])
    for (const phase of ['enter', 'exit'])
      for (const progress of [0, 0.13, 0.5, 0.9, 1])
        assert.deepEqual(
          k.resolveTemperaTransitionEffectFrame(kind, phase, progress, -Math.PI * 0.5),
          original.resolveTemperaTransitionEffectFrame(kind, phase, progress, -Math.PI * 0.5),
        );
  const image = { id: 'asset:1', align: 'left', verticalAlign: 'bottom', scale: 0.7, opacity: 0.5 };
  for (const seed of [0, 1, 127, -77])
    assert.deepEqual(
      k.resolveTemperaImagePlacement(image, seed),
      original.resolveTemperaImagePlacement(image, seed),
    );
});
