// END Folia Tempera source oracle
test('Native source render plan keeps actual painted prefix under inversion and inherits filter resolution', async () => {
  const { createSceneGraph } = await import(new URL('../sonnet/scene-graph.mjs', base));
  const { RenderPlanner } = await import(new URL('render-plan.mjs', base));
  const { createTemperaDifferenceFilter } = await import(
    new URL('temperaDifferenceFilter.mjs', base)
  );
  const p = createSceneGraph(),
    root = new p.Container(),
    back = new p.Graphics().rect(0, 0, 320, 240).fill(0x000000),
    text = new p.Container(),
    front = new p.Graphics().rect(100, 100, 40, 40).fill(0xffffff);
  root.addChild(back, text);
  text.addChild(front);
  text.filters = [createTemperaDifferenceFilter(p, { ink: '#ffffff', paper: '#000000' })];
  const planner = new RenderPlanner(),
    frame = planner.frame(root, 320, 240, 1.5, 1),
    filter = frame.stages.find((s) => s.kind === 'difference');
  assert.equal(filter.previous, frame.stages[0].id);
  assert.equal(filter.front, frame.stages[1].id);
  assert.equal(filter.resolution, 1.5);
  assert.deepEqual(filter.roi, [100, 100, 140, 140]);
  assert.equal(frame.output, filter.id);
  const same = planner.frame(root, 320, 240, 1.5, 2);
  assert.equal(same.resources.length, 0);
  assert.equal(same.stages.length, frame.stages.length);
  root.filters = [new p.BlurFilter({ resolution: 0.75, strength: 4, quality: 1, kernelSize: 5 })];
  const nested = new RenderPlanner().frame(root, 320, 240, 1.5, 3);
  assert.equal(nested.stages.find((s) => s.kind === 'difference').resolution, 0.75);
  assert.equal(nested.stages.find((s) => s.kind === 'filters').targetResolution, 1.5);
});
